python3 -c '
ys = [-100, -80, -60, -40, -20, 0, 20, 40, 60, 80, 100]
dfts = [4, 8, 12, 27, 32, 37, 32, 26, 13, 5, 3]

def interp(y):
    if y <= ys[0] or y >= ys[-1]:
        return 0.0
    for i in range(len(ys)-1):
        if ys[i] <= y <= ys[i+1]:
            t = (y - ys[i]) / (ys[i+1] - ys[i])
            return dfts[i] * (1 - t) + dfts[i+1] * t
    return 0.0

for P in [40, 45, 50, 55, 60, 65, 70]:
    vals = []
    for step in range(101):
        y = step * P / 100.0
        tot = sum(interp(y - k * P) for k in range(-15, 16))
        vals.append(tot)
    print(f"Pitch {P}mm: min={min(vals):.1f}, max={max(vals):.1f}, mean={sum(vals)/len(vals):.1f}, ripple={max(vals)-min(vals):.1f}")
'

